python
def duplicateCarriagePositiveInkInvoice(readings, k):
    a=readings
    out=[]
    write=0
    for read in range(len(a)):
        if write==0 or a[read]!=a[write-1]:
            a[write]=a[read]
            write+=1
    out=a[:write]
    return sum(x for x in out if x>0)


java
class Solution {
  public int duplicateCarriagePositiveInkInvoice(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int write=0;for(int read=0;read<a.length;read++)if(write==0||a[read]!=a[write-1])a[write++]=a[read];for(int i=0;i<write;i++)out.add(a[i]);}
    int answer=0;for(int x:out)if(x>0)answer+=x;return answer;
  }
}
